import base64 as _b64

def _img(name):
    """Return BytesIO PNG from embedded base64 image data."""
    data = _SHAPE_B64.get(name)
    if data is None:
        raise KeyError(f"No embedded image for shape {name!r}")
    return _b64.b64decode("".join(data.split()))

def _cone_mpl():
    """Cone rendered with clean fill-then-outline approach (no bleed)."""
    import matplotlib.patches as mpatches
    from matplotlib.patches import Ellipse as _Ellipse
    fig, ax = plt.subplots(figsize=(4.5, 4))
    ax.set_aspect("equal"); ax.axis("off")
    fig.patch.set_facecolor("white")
    r, yb = 0.42, -0.35
    # Fill body (no edge)
    ax.add_patch(MPoly([(-r,yb),(r,yb),(0,0.55)], closed=True,
                       facecolor=FILL_MID, edgecolor="none", zorder=1))
    # Fill base ellipse (no edge)
    ax.add_patch(_Ellipse((0,yb), 2*r, 0.18,
                          facecolor=FILL_DARK, edgecolor="none", zorder=2))
    # Draw outline edges separately with butt caps — no bleed
    ax.plot([-r,0],[yb,0.55], color=EDGE_COL, lw=EDGE_LW,
            solid_capstyle="butt", zorder=3)
    ax.plot([r,0],[yb,0.55], color=EDGE_COL, lw=EDGE_LW,
            solid_capstyle="butt", zorder=3)
    ax.add_patch(_Ellipse((0,yb), 2*r, 0.18,
                          facecolor="none", edgecolor=EDGE_COL,
                          linewidth=EDGE_LW, zorder=4))
    ax.set_xlim(-0.68, 0.68); ax.set_ylim(-0.58, 0.72)
    return _save(fig)


